\begin{lemma}
\label{lemma-tolev}
For  $k>1$ and $0 < \tau \le \dfrac{1}{2}$, we have that
\[
  \int_{-\tau}^{\tau} |\Stilde_{\phi}(\alpha)|^2 \, \dx \alpha
  \ll_{\phi}
  (\tau N^{1/k} + N^{2/k\,-1}) L^4.
\]
\end{lemma}

