ref_dict.equisuper:
\begin{prop}\label{equisuper}
  Let $0<T\le\infty$ and $f$ be a continuous and nondecreasing function such that $f(0) \ge 0$. Then, $\eqref{1.1}$ has a local-in-time nonnegative solution in $\RN\times(0, T)$ if and only if $\eqref{1.1}$ has a nonnegative supersolution $\overline{u} \in L^{\infty}((0, T), L^{1}_{\rm ul}(\RN)) \cap L^{\infty}_{\rm loc}((0, T), L^{\infty}(\RN))$. Moreover, if a nonnegative supersolution $\overline{u}$ exists, then the solution $u$ satisfies $0\le u(t) \le \overline{u}(t)$ for $0<t<T$. 
\end{prop}

ref_dict.keylemofkeyprop:
\begin{lem}\label{keylemofkeyprop}
  Let $f \in S_{q}$ with $q \in [1, \infty)$. Then, for any $\varepsilon>0$, there exists $\delta_{\varepsilon}>0$ such that 
  \begin{equation*}
    \rho^{-(q-\varepsilon)} f\left(F^{-1}(A) \right) \le f\left(F^{-1}(A\rho) \right) \le \rho^{-(q+\varepsilon)} f\left(F^{-1}(A) \right)
  \end{equation*}
  for $A \in (0, \delta_{\varepsilon})$ and $\rho\in (0, 1)$. 
\end{lem}

ref_dict.MainProp:
\begin{prop}\label{MainProp}
    Let $N \geq 1$, $0 < \gamma < \min\{2, N\}$ and $u_0 \geq 0$. Let $H\in C^{2}([0, \infty))$ satisfy $\eqref{(H)}$. Suppose that $f \in C([0, \infty))$ and $f$ is a nonnegative and nondecreasing function in $(0,\infty)$. Suppose that there exist $\theta \in (0, 1]$ and $\zeta \geq 0$ such that one of the following holds{\rm :} 
    \begin{itemize}
      \item[$\mathrm{(i)}$] $H(u_0) \in L^{1}_{\mathrm{ul}}(\mathbb{R}^N)$ and 
      \begin{equation}\label{3.1}
        \lim_{\eta \to \infty} \Phi(\eta) \int_{\eta}^{\infty} \frac{\Psi(\tau) H'(\tau)}{H(\tau)^{1 + \frac{2-\gamma}{N}}} \left(1 - \left(\frac{H(\eta)}{H(\tau)}\right)^{\frac{2}{N}} \right)^{-\frac{\gamma}{2}} \,d\tau = 0, 
      \end{equation}

      \item[$\mathrm{(ii)}$] $H(u_0) \in \mathcal{L}^{1}_{\mathrm{ul}}(\mathbb{R}^N)$ and 
      \begin{equation}\label{3.2}
        \limsup_{\eta \to \infty} \Phi(\eta) \int_{\eta}^{\infty} \frac{\Psi(\tau) H'(\tau)}{H(\tau)^{1 + \frac{2-\gamma}{N}}} \left(1 - \left(\frac{H(\eta)}{H(\tau)}\right)^{\frac{2}{N}} \right)^{-\frac{\gamma}{2}} \,d\tau < \infty, 
      \end{equation}
    \end{itemize}
    where 
    \begin{equation*}
      \Phi(\xi) := \sup_{\zeta \leq \sigma \leq \xi} \frac{H'(\sigma)}{H(\sigma)^{1-\theta}} \quad \text{and} \quad \Psi(\xi) := \sup_{\zeta \leq \sigma \leq \xi} \frac{f(\sigma)}{H(\sigma)^{\theta}}. 
    \end{equation*}
    Then, there exists $T>0$ such that $\eqref{1.1}$ has a local-in-time nonnegative solution $u$ in $\RN \times (0,T)$. Moreover, there exists $C > 0$ depending on $N$ and $u_0$ such that 
    \begin{equation}\label{MainProp-est}
      \|H(u(t))\|_{L^{1}_{\mathrm{ul}}(\mathbb{R}^N)} \leq C \quad \text{for}~~0<t<T. 
    \end{equation}
\end{prop}

ref_dict.Nonexist-lem:
\begin{lem}\label{Nonexist-lem}
  Suppose that $f$ satisfies the same assumptions as in Theorem~$\ref{Nonexist-thm}$. Let $u_0\in L^{1}_{\rm ul}(\RN)$ and assume that there exists a local-in-time nonnegative solution $u$ to problem $\eqref{1.1}$ in $\RN\times(0,T)$ with initial function $u_0$ for some $T>0$. Then, there exists $C>0$ depending on $\delta$, $N$ and $\gamma$ such that 
  \begin{equation*}
    [e^{t\Delta} u_0](0) \le F^{-1}(C t^{1-\frac{\gamma}{2}})
  \end{equation*}
  for $t\in(0,T)$. 
\end{lem}

post_theorem_intro_text:
\begin{rem}
  \begin{itemize}
    \item[$\mathrm{(i)}$] By Theorem~$\ref{Exist-thm}$, we obtain the sufficient conditions with respect to $r$ and $q$ for local existence of $\eqref{1.1}$ $(\text{see {\bf Fig.~\ref{q-rplane}}})$. Note that Theorem~$\ref{Exist-thm}$ does not cover the doubly critical case $q=1+r$ and $r=N/(2-\gamma)$. 
    \item[$\mathrm{(ii)}$] In the cases $q<1+r$ or $q=1+r$ with $\eqref{sub-assum}$, $F(\xi)^{-r}$ is convex for large $\xi>0$. Thus, if $F(u_0)^{-r}\in L^{1}_{\rm ul}(\RN)$, then $u_0\in L^{1}_{\rm ul}(\RN)$ and hence, $e^{t\Delta}u_0<\infty$ for $t>0$. 
  \end{itemize}
\end{rem}

We prove Theorem~\ref{Exist-thm} by so-called supersolution method (see Proposition~\ref{equisuper}). In particular, we employ the argument by Miyamoto--Suzuki \cite[Theorem~A]{MS21} for $\eqref{nosing}$. In our case, we need to take care of the term $|\cdot|^{-\gamma}$ in $\eqref{1.1}$. To handle this, we use H\"{o}lder's inequality and Jensen's inequality with some estimate of the heat kernel, and then we obtain the estimate of the integral term of a supersolution, see a proof of Lemma~\ref{3lem1} for detail. Furthermore, in the critical case (iii), we derive the estimate of $f(F^{-1}(\cdot))$ (see Lemma~\ref{keylemofkeyprop}) and show the convergence of $\eqref{3.2}$. 

Next, we state the nonexistence results of local-in-time solutions to $\eqref{1.1}$. 

\begin{thm}\label{Nonexist-thm}
  Suppose that $f \in C^{2}([0, \infty)) \cap S_{q}$ with $q \in [1, \infty)$ and 
  \begin{equation}\label{Nonexist-assum}
    \frac{f(\xi) f''(\xi)}{(f'(\xi))^{2}}\ge\delta \quad \text{for}~~\xi\ge 0
  \end{equation}
  for sufficiently small $\delta>0$. Let $0<r<N/(2-\gamma)$ and $q \le 1+r$. Then, there exists a nonnegative initial function $u_0 \in L^{1}_{\rm ul}(\RN)$ such that $F(u_0)^{-r} \in L^{1}_{\rm ul}(\RN)$ and $\eqref{1.1}$ does not have nonnegative local-in-time solutions. 
\end{thm}

\begin{figure}[t]
  \centering
  \input{Figure1.tex}
  \caption{Existence and nonexistence area of a local-in-time solution in Theorem~\ref{Exist-thm} and Theorem~\ref{Nonexist-thm} . Existence~(i), (ii) and (iii) correspond to the results of Theorem~\ref{Exist-thm} (i), (ii) and (iii), respectively.}
  \label{q-rplane}
\end{figure}

\begin{rem}
  \begin{itemize}
    \item[$\mathrm{(i)}$] By Theorem~$\ref{Nonexist-thm}$, we obtain the conditions on $r$ and $q$ for the nonexistence of local-in-time solutions to $\eqref{1.1}$ $(\text{see {\bf Fig.~\ref{q-rplane}}})$.  
    \item[$\mathrm{(ii)}$] Theorem~$\ref{Exist-thm}$ and Theorem~$\ref{Nonexist-thm}$ imply that $\eqref{OIC}$ is the optimal integrability condition of initial function $u_0$ for local solvability of $\eqref{1.1}$. 
    \item[$\mathrm{(iii)}$] The assumption $\eqref{Nonexist-assum}$ is important for our approach because we use the convexity of $f^{1-\delta}$. We note that $\eqref{Nonexist-assum}$ holds if $f(\xi) = \xi^{p}$ $(p>1)$ or $f(\xi) = e^{\xi}$. 
  \end{itemize}
\end{rem}

We prove Theorem~\ref{Nonexist-thm} by contradiction which is based on the argument in \cite{ACCL25}, \cite{FI21} and \cite{MS21} etc. for $\eqref{nosing}$. Similar to Theorem~\ref{Exist-thm}, we need to take care of the term $|\cdot|^{-\gamma}$ in $\eqref{1.1}$. To take care of them, we use the condition $\eqref{Nonexist-assum}$ and derive the reverse H\"{o}lder's inequality. Then, we obtain the necessary condition for the existence of local-in-time nonnegative solutions to $\eqref{1.1}$ (see Lemma~\ref{Nonexist-lem}). By using this necessary condition, we prove Theorem~\ref{Nonexist-thm} by the contradiction argument. 

The outline of the paper is as follows. In Section~2, we introduce several properties of uniformly local Lebesgue space $L^{r}_{\rm ul}(\RN)$. We also give a pointwise estimate of $e^{(t-s)\Delta}[\left|\cdot\right|^{-\alpha}e^{s\Delta}\phi]$, which is necessary to control the nonlinear term. In Section~3, we introduce an abstract existence result for $\eqref{1.1}$ and give a sufficient condition on the existence of local-in-time solution to problem $\eqref{1.1}$ (see Proposition~\ref{MainProp}). As an application of Proposition~\ref{MainProp}, we prove Theorem~\ref{Exist-thm}. In Section~4, we show some lemma needed to prove Theorem~\ref{Nonexist-thm} and show a proof of Theorem~\ref{Nonexist-thm}. 

Throughout this paper, we will use $C$ to denote generic positive constants and $C$ may take different values within a calculation.

