We prove Theorem~\ref{Exist-thm} by a so-called supersolution method. Specifically, we use the following proposition.

\begin{prop}\label{equisuper}
  Let $0<T\le\infty$ and $f$ be a continuous and nondecreasing function such that $f(0) \ge 0$. Then, $\eqref{1.1}$ has a local-in-time nonnegative solution in $\RN\times(0, T)$ if and only if $\eqref{1.1}$ has a nonnegative supersolution $\overline{u} \in L^{\infty}((0, T), L^{1}_{\rm ul}(\RN)) \cap L^{\infty}_{\rm loc}((0, T), L^{\infty}(\RN))$. Moreover, if a nonnegative supersolution $\overline{u}$ exists, then the solution $u$ satisfies $0\le u(t) \le \overline{u}(t)$ for $0<t<T$. 
\end{prop}

We employ the argument by Miyamoto--Suzuki (see Miyamoto--Suzuki, Theorem~A, MS21) for
\begin{equation} 
  \label{nosing} 
  \left\{ 
  \begin{array}{lll} 
  \partial_t u - \Delta u = f(u), &x \in \RN, ~ t\in (0, T), \vspace{3pt} \\ 
  u(x,0)=u_0(x) \geq 0, &x \in \RN. 
  \end{array} 
  \right. 
\end{equation}
In our case, we need to take care of the term $|\cdot|^{-\gamma}$ in
\begin{equation} 
  \label{1.1} 
  \left\{ 
  \begin{array}{ll} 
  \partial_t u - \Delta u = |x|^{-\gamma} f(u), &x \in \RN, ~ t\in (0, T), \vspace{3pt} \\ 
  u(x,0)=u_0(x) \ge 0, &x \in \RN, 
  \end{array} 
  \right. 
\end{equation}
To handle this, we use H\"older's inequality and Jensen's inequality with some estimate of the heat kernel, and then obtain an estimate of the integral term of a supersolution. We use the lemma below.

\begin{lem}\label{3lem1}
  Assume the same conditions as in Proposition~$\ref{MainProp}$. Let $u_1$ and $\overline{u}$ be as in $\eqref{u_1def}$ and $\eqref{ssdef}$, respectively. Then, $\overline{u}$ belongs to $L^{\infty}((0, \infty), L^{1}_{\rm ul}(\RN))\cap L^{\infty}_{\rm loc}((0, \infty), L^{\infty}(\RN))$. Furthermore, there exists $C>0$ depending only on $N$, $\gamma$ and $\theta$ such that
  \begin{equation}\label{ssest1}
    e^{(t-s)\Delta}\left[|\cdot|^{-\gamma} H(\overline{u}(s))^{\theta}\right] \le C t^{\frac{\gamma}{2}} H(\overline{u}(t))^{\theta} (t-s)^{-\frac{\gamma}{2}} s^{-\frac{\gamma}{2}} \quad \text{for}~~0<s<t. 
  \end{equation}
\end{lem}

Furthermore, in the critical case (iii), we derive an estimate of $f(F^{-1}(\cdot))$ using the following lemma,

\begin{lem}\label{keylemofkeyprop}
  Let $f \in S_{q}$ with $q \in [1, \infty)$. Then, for any $\varepsilon>0$, there exists $\delta_{\varepsilon}>0$ such that 
  \begin{equation*}
    \rho^{-(q-\varepsilon)} f\left(F^{-1}(A) \right) \le f\left(F^{-1}(A\rho) \right) \le \rho^{-(q+\varepsilon)} f\left(F^{-1}(A) \right)
  \end{equation*}
  for $A \in (0, \delta_{\varepsilon})$ and $\rho\in (0, 1)$. 
\end{lem}

and show the convergence of
\begin{equation}\label{3.2}
        \limsup_{\eta \to \infty} \Phi(\eta) \int_{\eta}^{\infty} \frac{\Psi(\tau) H'(\tau)}{H(\tau)^{1 + \frac{2-\gamma}{N}}} \left(1 - \left(\frac{H(\eta)}{H(\tau)}\right)^{\frac{2}{N}} \right)^{-\frac{\gamma}{2}} \,d\tau < \infty, 
      \end{equation}
This completes the proof of the main theorem.

