theorem.content:
[Quantitative Pansu]\label{main thm: pansu}
 Let $(G,d)$ be a geodesic Lie group. Assume $G$ is simply connected and nilpotent.
 After fixing an asymptotic grading, consider the associated Pansu limit metric $d_\infty$ on $G$ and the constants $\alpha_\infty$ and $\beta$ defined in \eqref{def_alpha_inf} and \eqref{def_beta}, respectively. Then, for some $C>0$, we have 
 \begin{align}\label{eq: main pansu1}
  \left|d(p,q)-d_\infty(p,q)\right| \leq C\max\left\{d_\infty(1,p),d_\infty(1,q)\right\}^{1-\alpha_\infty/\beta}, \quad \forall p\in G, \;\forall q \in G \setminus B_{d_\infty}(1,1).
 \end{align}

ref_dict.def_alpha_inf:
\begin{eqnarray}\nonumber
   \alpha_{\infty}&\coloneqq & \alpha_{\infty}(\Delta, (V_i)_i) \\\nonumber
   &\coloneqq &\min\{\alpha_{(1,\infty)}, \alpha_{(2,\infty)}\}
   \\\label{def_alpha_inf}
   &=& 
   \max \left\{j \in \mathbb{N} \, : 
   \begin{cases}
    k \in \mathbb{N}, \; p \in \mathbb{N}^k, \;\\ v \in \Delta \end{cases}\implies \begin{cases}
     [V_{p_1},\ldots,V_{p_k}] \subseteq V_{|p|} \oplus V_{\geq |p|+j}, \,\\
   \, v-\pi_1(v) \in \mathfrak{g}^{(j+1)} 
   \end{cases}\right\}
   .
\end{eqnarray}

ref_dict.main thm: mitchell:
\begin{thm}[Quantitative Mitchell]\label{main thm: mitchell}
 Let $(G,d)$ be a Lie group equipped with a left-invariant geodesic metric. After fixing a tangent grading, consider the associated tangent metric $d_0$ on a bounded neighborhood $U$ of the identity in $G$ and the constants $\alpha_0$ and $\beta$ defined in \eqref{def_alpha0} and \eqref{def_beta}, respectively. Then, for some $C>0$, we have 
  \begin{align*}
  &-Cd(p,q)^{1/\beta}d_0(1,p)^{1+(\alpha_0 -1)/\beta}\\
     &\leq d(p,q)-d_0(p,q)\\
     &\leq Cd_0(p,q)^{1/\beta}d_0(1,p)^{1+(\alpha_0 -1)/\beta}  \quad \forall p,q \in U \text{ with } d_0(1,p) \geq d_0(1,q).
 \end{align*}
 In particular, we have 
\begin{align}\label{eq: cor mitchell1}
  |d(p,q)-d_0(p,q)| \leq C\max\{d_0(1,p),d_0(1,q)\}^{1+\alpha_0/\beta}, \quad \forall p,q \in U.
 \end{align}
\end{thm}

