ref_dict.t-bi:
\begin{theorem}\label{t-bi}
Let $g:U_{-1}\to U_0$ be a proper holomorphic map of degree $d\ge 2$ where $U_{-1}, U_0$ are open simply connected subsets of $\C$ such that $U_{-1}\subset U_0$.
Suppose that $X\subset U_0$ is a compact and full (i.e. $\C\setminus X$ is connected) set which is completely invariant, i.e.,
$g^{-1}(X)=X$, and contains all critical points of $g$. Then there exists a polynomial-like restriction $g:V'\to V$ where $V', V$ are neighborhoods of $X$.
\end{theorem}

ref_dict.t-m:
\begin{theorem}\label{t-m}
Let $\mathcal{G}=\{g_n\}_{n=0}^\infty$ where $g_n\in E_{\beta_n}(J_n)$, $n=0,1,2,...$, and $\beta_n$, $J_n$ are as follows:
\begin{enumerate}\label{e-t}
\item $\beta_0=1$, $|\beta_n|<|\beta_{n+1}|$ for $n=0,1,2,,,$, and $\beta_n\to\infty$,
\item if $I_n=<-\beta_n,\beta_n>$, then $I_n\subset J_n\subset I_{n+1}$, $n=0,1,2,...$,
\item for every $n>0$ there exists an integer $p_n\ge 2$, such that
$$g_0(x)=g_n^{p_n}(x), \mbox{ for all } x\in [-1,1].$$
\end{enumerate}
Then there exists a simply connected neighborhood $V\subset C_{J_0}$ of $[-1,1]$, such that $\overline{V'}\subset V$ where $V'=g_0^{-1}(V)$.
In other words, $g_0: V'\to V$ is a PL restriction of the map $g_0:\Omega_{g_0}\to \C_{J_0}$.

Moreover, assuming
\begin{equation}\label{label-m}
K_1\le \frac{|J_n|}{|I_n|}\le K_2, \
|I_n|\le\Lambda^n, \ p_n\le N^n,
\end{equation}
for some $1<K_1<K_2<\infty$, $\Lambda>1$, $N\ge 2$ and all $n$, the following uniform bounds holds:
there exists $m=m(K_1,K_2,\Lambda,N)>0$
such that $\mod(V\setminus \overline{V'})\ge m$, for any $\mathcal{G}$ as above and for a choice of the domain $V$.
\end{theorem}

theorem.content:
\label{Main}
Let $(\bar{v},\bar{u},\bar{\phi})$ be the shock profile described in Lemma~\ref{SP}, and let $L$ denote the linear operator defined in \eqref{Ldef}--\eqref{calAB}. There exists a constant $\delta_1>0$ such that if the shock strength $\delta_S$ is less than $\delta_1$, then the shock profile is strongly spectrally stable in $L^2$. That is,
\begin{equation} \label{sstability}
\sigma(L) \cap \{ \lambda \in \mathbb{C}: \operatorname{Re}{\lambda} \geq 0 \} = \{0\},
\end{equation}
where $\sigma(L)$ denotes the spectrum of $L$ on $L^2(\mathbb{R}) \times L^2(\mathbb{R})$. Moreover, $\lambda =0$ is an eigenvalue of $L$ with algebraic multiplicity one.

