ref_dict.agree:
\begin{remark} \label{agree}
On any simply connected subset of the domain of consistent splitting, zeros of the Evans function correspond to eigenvalues of $L$, counted with algebraic multiplicity; see \cite{GJ1,GJ2}. The analytic extension constructed above (cf. Lemma~\ref{lemma0.2}) preserves this property. Indeed, it can be interpreted within the \emph{extended spectral theory}, in which the order of vanishing of $\mathcal D(\lambda)$ agrees with the algebraic multiplicity of $\lambda$ as an \emph{effective} eigenvalue; see \cite[Section~6]{ZH}.
\end{remark}

ref_dict.Rem_E-cond:
\begin{remark} \label{Rem_E-cond}
The statement in Theorem~\ref{Main} that $\lambda=0$ has algebraic multiplicity one is understood in the sense that the (extended) Evans function associated with the eigenvalue problem for $L$ has a simple zero at $\lambda=0$; see Remark~\ref{agree}. With this interpretation, the result in Theorem~\ref{Main} may be rewritten as the following conditions for the Evans function $\mathcal D(\lambda)$:
\smallskip
\begin{enumerate}
\item[$(\textbf{D1})$] $\mathcal{D}(\cdot)$ has no zeros in $\{ \operatorname{Re} \lambda \geq 0 \} \setminus \{ 0 \}$.
\item[$(\textbf{D2})$] $(d/d\lambda) \mathcal{D}(0) \neq 0$.
\end{enumerate}
\smallskip
Here $(\textbf{D1})$ is implied by \eqref{sstability}, and $(\textbf{D2})$ encodes the above simplicity statement at $\lambda=0$. We note that the Evans-function conditions $(\textbf{D1})$--$(\textbf{D2})$ are necessary and sufficient conditions for linearized and nonlinear stability of shock profiles for a general system of viscous conservation laws in one space dimension \cite[Section~1.4.2]{ZJL}; see also \cite{MZ3, MZ4, MZ5}. As shown in Proposition~\ref{D'rel}, the condition $(\textbf{D2})$ is equivalent to
\begin{equation}
\Gamma \Delta \neq 0,
\end{equation}
where $\Gamma$ measures transversality of the connection between $(v_-,u_-,\phi_-)$ and $(v_+,u_+,\phi_+)$ given by the profile $(\bar{v},\bar{u},\bar{\phi})$, and $\Delta$ is the Liu--Majda determinant for the corresponding shock of the associated hyperbolic system, namely the quasi-neutral Euler system:
\begin{equation*}
\begin{split}
& v_t - u_y =0, \\
& u_t + (T+1) \left( \frac{1}{v} \right)_y =0,\\
& \phi = - \ln v.
\end{split}
\end{equation*}
This system can be obtained by taking the formal limits $\varepsilon \to 0$ and $\nu \to 0$ in \eqref{NSP}. For further discussion of the relation \eqref{gDel} and the associated transversality coefficient in the context of viscous shock profiles, we refer the reader to \cite[Section~1.4]{MZ2}.
\end{remark}

ref_dict.SP:
\begin{lemma}[\cite{DLZ}, Proposition~1.9] \label{SP}
For given $(v_-,u_-)$ with $v_->0$, there exists a positive constant $\delta_0>0$ such that for any $(v_+,u_+,s)$ satisfying \eqref{RH}, \eqref{Lax}, and
\begin{equation*}
|v_+-v_-| =: \delta_S < \delta_0,
\end{equation*}
the ODE system \eqref{waveeq} admits a unique (up to a shift) shock profile $(\bar{v},\bar{u},\bar{\phi})(x)$ satisfying \eqref{ffcond} and
\begin{equation} \label{sprel}
s\bar{v}_x = -\bar{u}_x >0, \quad \underline{C} \bar{u}_x \leq \bar{\phi}_x \leq \overline{C} \bar{u}_x
\end{equation}
for some positive constants $\underline{C}$, $\overline{C}$. Moreover, the unique solution satisfying $\textstyle \bar{v}(0)=\frac{v_-+v_+}{2}$ verifies the derivative bounds
\begin{equation} \label{spbound}
\begin{cases}
\left| \frac{d^k}{dx^k} (\bar{v}-v_+, \bar{u}-u_+,\bar{\phi}-\phi_+) \right| \leq C_k \delta_S^{k+1} e^{-\theta \delta_S |x|}, & x>0 \\
\left| \frac{d^k}{dx^k} (\bar{v}-v_-, \bar{u}-u_-,\bar{\phi}-\phi_-) \right| \leq C_k \delta_S^{k+1} e^{-\theta \delta_S |x|}, & x<0
\end{cases}
\end{equation}
for $k \in \mathbb{N} \cup \{0 \}$, where $C_k>0$ and $\theta>0$ are generic constants.
\end{lemma}

ref_dict.Main:
\begin{theorem} \label{Main}
Let $(\bar{v},\bar{u},\bar{\phi})$ be the shock profile described in Lemma~\ref{SP}, and let $L$ denote the linear operator defined in \eqref{Ldef}--\eqref{calAB}. There exists a constant $\delta_1>0$ such that if the shock strength $\delta_S$ is less than $\delta_1$, then the shock profile is strongly spectrally stable in $L^2$. That is,
\begin{equation} \label{sstability}
\sigma(L) \cap \{ \lambda \in \mathbb{C}: \operatorname{Re}{\lambda} \geq 0 \} = \{0\},
\end{equation}
where $\sigma(L)$ denotes the spectrum of $L$ on $L^2(\mathbb{R}) \times L^2(\mathbb{R})$. Moreover, $\lambda =0$ is an eigenvalue of $L$ with algebraic multiplicity one.
\end{theorem}

ref_dict.D'rel:
\begin{proposition} \label{D'rel}
Assume that the hypotheses of Theorem~\ref{Main} hold. Let $\mathcal D(\lambda)$ be the Evans function for \eqref{5} defined by \eqref{Evans}--\eqref{relabel}. Then, we have
\begin{equation}\label{gDel}
\mathcal D'(0) = \Gamma \Delta,
\end{equation}
where $\Gamma$ is a constant measuring transversality of the intersection of the stable and unstable manifolds spanned by the bases $\{\varphi_1^+, \varphi_2^+\}$ and $\{\varphi_3^-,\varphi_4^-,\varphi_5^- \}$, respectively, and $\Delta$ is defined by
\begin{equation} \label{LMdet}
\Delta := \det \left( U_+ - U_-, r_2^- \right).
\end{equation}
In particular, $\Gamma\neq 0$ if and only if this intersection is transverse.
\end{proposition}

