\[
\mathcal{D}'(0)=\Gamma\Delta.
\]
Then the Rankine--Hugoniot relation
\begin{equation} \label{RH}
\begin{split}
& -s (v_+-v_-)-(u_+-u_-)=0, \\
& -s (u_+-u_-)+(T+1)\left(\frac{1}{v_+} - \frac{1}{v_-} \\right) = 0,
\end{split}
\end{equation}
implies $\Delta\neq0$, so it remains to show $\Gamma\neq0$. The transversality of the small-amplitude shock profiles follows essentially from their construction in \cite[Section~2]{DLZ} via a center manifold reduction: near an equilibrium the dynamics reduce to a one-dimensional equation on the center manifold, with a heteroclinic orbit that is unique up to translation, while the complementary subspace has an exponential dichotomy. These two observations imply the transverse connection and hence $\Gamma\neq 0$ for sufficiently small amplitudes. Therefore $\mathcal D'(0)\neq0$, implying that $\lambda=0$ has algebraic multiplicity one, which completes the proof of the main theorem.

expanded_theorem:
\label{Main}
Let $(\bar{v},\bar{u},\bar{\phi})(x)$ be the shock profile given by the following lemma.

\begin{lemma}[\cite{DLZ}, Proposition~1.9] \label{SP}
For given $(v_-,u_-)$ with $v_->0$, there exists a positive constant $\delta_0>0$ such that for any $(v_+,u_+,s)$ satisfying \eqref{RH}, \eqref{Lax}, and
\begin{equation*}
|v_+-v_-| =: \delta_S < \delta_0,
\end{equation*}
the ODE system \eqref{waveeq} admits a unique (up to a shift) shock profile $(\bar{v},\bar{u},\bar{\phi})(x)$ satisfying \eqref{ffcond} and
\begin{equation} \label{sprel}
s\bar{v}_x = -\bar{u}_x >0, \quad \underline{C} \bar{u}_x \leq \bar{\phi}_x \leq \overline{C} \bar{u}_x
\end{equation}
for some positive constants $\underline{C}$, $\overline{C}$. Moreover, the unique solution satisfying $\textstyle \bar{v}(0)=\frac{v_-+v_+}{2}$ verifies the derivative bounds
\begin{equation} \label{spbound}
\begin{cases}
\left| \frac{d^k}{dx^k} (\bar{v}-v_+, \bar{u}-u_+,\bar{\phi}-\phi_+) \right| \leq C_k \delta_S^{k+1} e^{-\theta \delta_S |x|}, & x>0 \\
\left| \frac{d^k}{dx^k} (\bar{v}-v_-, \bar{u}-u_-,\bar{\phi}-\phi_-) \right| \leq C_k \delta_S^{k+1} e^{-\theta \delta_S |x|}, & x<0
\end{cases}
\end{equation}
for $k \in \mathbb{N} \cup \{0 \}$, where $C_k>0$ and $\theta>0$ are generic constants.
\end{lemma}

Let $L$ denote the linear operator defined by
\begin{equation} \label{Ldef}
LU := \left(A U \right)_x + \left( B U_x \right)_x + \left(D ( \mathcal{A}^{-1}\mathcal{B} U )_x \right)_x + \left(E ( \mathcal{A}^{-1}\mathcal{B} U )_{xx} \right)_x,
\end{equation}
where
\begin{equation} \label{calAB}
\begin{split}
\mathcal{A} & =\bar{v} e^{\bar{\phi}}+ \frac{\varepsilon^2 \bar{v}_x}{\bar{v}^2} \partial_x-\frac{\varepsilon^2}{\bar{v}} \partial_{xx}, \quad \mathcal{B} = -e^{\bar{\phi}} -\frac{\varepsilon^2 \bar{\phi}_{xx}}{\bar{v}^2} + \frac{2\varepsilon^2 \bar{v}_x \bar{\phi}_x}{\bar{v}^3}-\frac{\varepsilon^2 \bar{\phi}_x}{\bar{v}^2} \partial_x.
\end{split}
\end{equation}
There exists a constant $\delta_1>0$ such that if the shock strength $\delta_S$ is less than $\delta_1$, then the shock profile is strongly spectrally stable in $L^2$. That is,
\begin{equation} \label{sstability}
\sigma(L) \cap \{ \lambda \in \mathbb{C}: \operatorname{Re}{\lambda} \geq 0 \} = \{0\},
\end{equation}
where $\sigma(L)$ denotes the spectrum of $L$ on $L^2(\mathbb{R}) \times L^2(\mathbb{R})$. Moreover, $\lambda =0$ is an eigenvalue of $L$ with algebraic multiplicity one.,

