\label{intro:maintheo}
Let $\O$ be an open bounded domain in $\mathbb{R}^2$ which contains the origin, $\{0\}\subset \O$. Assume that
$v_n$ is a sequence of solutions of
\begin{equation}\label{intro:eq}
 -\D v_n=\left({\epsilon_n^2+|x|^2}\right)^{\alpha_n}V_n(x)e^{\displaystyle v_n} \qquad\text{in} \,\,\, \Omega,
\end{equation}
satisfying
\begin{equation}
 \label{intro:alphan}
 \a_n\to\a_\infty\in(-1,+\ii),
\end{equation}
and
\begin{equation}\label{intro: Vn}
 0<a\leq V_n\leq b<+\ii, \quad V_n\in C^{0}(\O), \quad V_n\to V \,\, \text{locally uniformly in}\,\,{\O}.
\end{equation}
with
$$
\alpha_\infty\in (-1,1).
$$
Then, for any
 $$ C_1>\max\left\{1,\tfrac{1+\alpha_\infty}{1-\alpha_\infty}\right\}$$
and for any compact set $K\subset\O$, there exists a constant $C_2>0$, which depends only by $a,b,dist(K,\partial\O), \alpha_\infty$ and by the
uniform modulus of continuity of $V$ on $K$, such that,
\begin{equation}
 \label{intro:sup+Cinf}
 \underset{K}\sup\, v_n + C_1\underset{\O}\inf\, v_n\leq C_2.
\end{equation}

theorem.content:
\label{THM:almost-balanced-exact}
    Suppose that $F$ is an almost balanced complete $r$-partite graph on $\ell \ge r+1$ vertices, and let $m = m_{r, \ell}$. Then
    \begin{align*}
        i(F) = \kappa_F \cdot \frac{(m-1)_{r-1}}{m^{\ell-1}}. 
    \end{align*}
    Moreover, there exists a constant $N_F$ such that for all $n \ge N_F$, the $m$-partite Tur\'{a}n graph $T_m(n)$ is the unique extremal graph for $I(F,n)$.

ref_dict.THM:Kr(t)-exact:
\begin{theorem}\label{THM:Kr(t)-exact}
    Let $r, t \geq 2$ be integers. The following holds for every $n \ge rt$. 
    Suppose that $G$ is an $n$-vertex complete multipartite graph satisfying $I(K_r(t),G) = I(K_r(t), n)$. Then $G \cong T_k(n)$ for some integer $k \ge r$. 
    In particular, for every integer $n \ge rt$, there exists an integer $k$ such that $I(K_r(t),T_k(n)) = I(K_r(t), n)$. 
\end{theorem}

ref_dict.SUBSEC:proof-perfect-stability-large:
\begin{proof}
        Fix a subset $B \subseteq [m]$ with $|B| = q$. 
        Recall that $G_{B}$ is the graph obtained from $G$ by adding a new vertex $v_{\ast}$ that is adjacent to precisely all vertices in $\bigcup_{i \in B} V_i$. 
        By symmetry, we may assume that $B = \{1, \ldots, q\}$. 

        Let $\tilde{\mathcal{C}}_{q}$ denote the collection of all induced copies of $F$ in $G_A$ that contain $v_{\ast}$. 
        Let $\tilde{\mathcal{C}}_{q}^{1}$ denote the collection of all induced copies of $F$ in $G_A$ in which $v_{\ast}$ forms a part of size one, and let $\tilde{\mathcal{C}}_{q}^{2}$ denote the collection of all induced copies of $F$ in $G_A$ in which $v_{\ast}$ lies in a part of size two.

        Note that the size of $\tilde{\mathcal{C}}_{q}^{1}$ coincides with the value of $I(K_{a_1, \ldots, a_{r-1}}, K[V_1, \ldots, V_{q}])$, which, by Fact~\ref{FACT:Directly-Computation-handy}, is 
        \begin{align*}
             \frac{(1+o(1)) (q)_{r-1}}{2^{\ell-r} (\ell-r)! (2r-\ell-1)!} k^{\ell-1}. 
        \end{align*}

        Note that the size of $\tilde{\mathcal{C}}_{q}^{2}$ coincides with the value of $I(K_{a_2, \ldots, a_{r}}, K[V_1, \ldots, V_{q}) \cdot \sum_{i=q+1}^{m}|V_i|$, which, by Fact~\ref{FACT:Directly-Computation-handy},~is 
        \begin{align*}
            \frac{(1+o(1))  (q)_{r-1}}{2^{\ell-r-1} (\ell-r-1)! (2r-\ell)!} k^{\ell-2} \cdot (m-q) k
            = \frac{(1+o(1)) (m-q) (q)_{r-1}}{2^{\ell-r-1} (\ell-r-1)! (2r-\ell)!} k^{\ell-1}. 
        \end{align*}

        Therefore, 
        \begin{align*}
            |\tilde{\mathcal{C}}_{q}|
            = |\tilde{\mathcal{C}}_{q}^{1}| + |\tilde{\mathcal{C}}_{q}^{2}|
            & = \frac{(1+o(1)) (q)_{r-1}}{2^{\ell-r} (\ell-r)! (2r-\ell-1)!} k^{\ell-1} + \frac{(1+o(1)) (m-q) (q)_{r-1}}{2^{\ell-r-1} (\ell-r-1)! (2r-\ell)!} k^{\ell-1} \\
            & = \frac{(1+o(1)) (q)_{r-1}}{2^{\ell-r} (\ell-r)! (2r-\ell)!} \big((2r-\ell) + 2(m-q) (\ell-r-1)\big) k^{\ell-1} 
             = \frac{(1+o(1)) h(q)}{2^{\ell-r} (\ell-r)! (2r-\ell)!} k^{\ell-1}.  
        \end{align*}
        This proves Claim~\ref{CLAIM:small-stable-S2}. 
    \end{proof}
    Fix an arbitrary set $A \subseteq [m]$ with $|A| \neq m-1$. 
    Let 
    \begin{align*}
        \Delta 
        \coloneqq \min\big\{ I(F, G_{A^{\ast}}) \colon A^{\ast} \subseteq [m] \text{ and } |A^{\ast}| = m-1 \big\} - I(F, G_A). 
    \end{align*}
    Then it follows from Claim~\ref{CLAIM:small-stable-S2} and Lemma~\ref{LEMMA:stable-small-inequality} that 
    \begin{align*}
        \Delta
        & = \frac{(1+o(1)) h(m-1)}{2^{\ell-r} (\ell-r)! (2r-\ell)!} k^{\ell-1} - \frac{(1+o(1)) h(|A|)}{2^{\ell-r} (\ell-r)! (2r-\ell)!} k^{\ell-1} \\
        & = \frac{h(m-1) - h(|A|)}{2^{\ell-r} (\ell-r)! (2r-\ell)!} k^{\ell-1} + o(k^{\ell-1}) 
        \ge \frac{1}{2^{\ell-r} (\ell-r)! (2r-\ell)!} k^{\ell-1} + o(k^{\ell-1}) 
        \ge \varepsilon n^{\ell-1}. 
    \end{align*}
    This shows that~\eqref{cond:S2} holds.   
    So it follows from Theorem~\ref{THM:Stability-Verification} that the inducibility problem for $F$ is perfectly stable, which completes the proof of Theorem~\ref{THM:almost-balanced-perfect-stability} for $\ell \le 2r-1$.
\end{proof}

\subsection{Proof of Theorem~\ref{THM:almost-balanced-perfect-stability} for $\ell \ge 2r$}\label{SUBSEC:proof-perfect-stability-large}
In this subsection, we prove Theorem~\ref{THM:almost-balanced-perfect-stability} for the case $\ell \ge 2r$.
The proof parallels that of the previous section, with several steps simplified by the fact that $a_r \ge 2$ (which follows from $\ell \ge 2r$).

\begin{lemma}\label{LEMMA:stable-large-inequality}
    Let $\ell, r$ be integers such that $r\ge 2$ and $\ell \ge 2r$. 
    Let $m = m_{r,\ell}$ be the integer given by Lemma~\ref{Lemma:Unique-Maximizer}. 
    Then the discrete function $H \colon [0, m] \to \mathbb{Z}$ defined by 
    \begin{align*}        H(q)
        \coloneqq (m-q)(q)_{r-1}, 
        \quad\text{for every}\quad q \in [0, m], 
    \end{align*}
    satisfies $H(q) < H(m-1)$ for all integers $q \in [0, m] \setminus \{m-1\}$.
\end{lemma}
\begin{proof}
    The inequality $H(q) < H(m-1)$ is clear for $q = m$ and $q \le r-2$ since $H(q) = 0$ in these cases. 
    For the remaining case, it suffices to show that $H(q)$ is increasing in $q$ for $q \in [r-1, m-2]$. 

    It follows from Lemma~\ref{Lemma:m-bounds}~\ref{Lemma:m-upper-bound} that 
    \begin{align}\label{eq:m<4r/3}
        m 
        < \frac{r\ell^2}{\ell^2-r^2}
        \le \frac{r(2r)^2}{(2r)^2-r^2}
        = \frac{4r}{3}. 
    \end{align}

    Fix $q \in [r, m-1]$. Then we have 
    \begin{align*}
        H(q) - H(q-1)
        & = (m-q)(q)_{r-1} - (m-q+1)(q-1)_{r-1} \\
        & = (q-1)_{r-2} \big((m-q)q - (m-q+1)(q-r+1)\big) \\
        & = (q-1)_{r-2} \big((r-1)(m+1)-rq\big) \\
        & \ge (q-1)_{r-2} \big(3r-1-m\big)
        > (q-1)_{r-2} \left(\tfrac{5r}{3}-1\right)
        > 0. 
    \end{align*}
    Here, in the first inequality we used the assumption that $q \le m-2$, in the second inequality we used~\eqref{eq:m<4r/3}. 
    This completes the proof of Lemma~\ref{LEMMA:stable-large-inequality}. 
\end{proof}

ref_dict.SUBSEC:proof-asymptotic-large:
\begin{enumerate}[label=(\roman*)]
            \item\label{CLAIM:OPT-all-equal-k-small-1} If $\ell \ge r+2$, then every maximizer $\bm{x} \in \OPT_{k+1}(F)$ is balanced.
            \item\label{CLAIM:OPT-all-equal-k-small-2} If $\ell = r+1$, then for every unbalanced maximizer $\bm{x} \in \OPT_{k+1}(F)$, there exists a balanced  maximizer $\bm{y} \in \OPT_{k+1}(F)$ such that $|\supp(\bm{y})| < |\supp(\bm{x})|$. 
        \end{enumerate}
    \end{claim}

    Recall that for every integer $t \ge r$, we have $p_F(\bm{t}) = \kappa_F \cdot f(t)$, with $f(t)$ defined in~\eqref{equ:def-fk}. 
    By Lemma~\ref{Lemma:Unique-Maximizer}, the function $f$ is strictly increasing on $[r,k]$, so $p_F(\bm{t}) < p_F(\bm{k})$ for every $t < k$. Hence, $i_{k+1}(F) = p_F(\bm{k})$.

    If $\ell \ge r+2$, then Claim~\ref{CLAIM:OPT-all-equal-k-small}~\ref{CLAIM:OPT-all-equal-k-small-1} immediately implies that $\OPT_{k+1}(F) = {\bm{k}}$.

    Now, suppose $\ell = r+1$. Take an arbitrary maximizer $\bm{x} \in \OPT_{k+1}(F)$. If $\bm{x} \neq \bm{k}$, then by Claim~\ref{CLAIM:OPT-all-equal-k-small}~\ref{CLAIM:OPT-all-equal-k-small-2} we obtain another balanced maximizer $\bm{y} \in \OPT_{k+1}(F)$ with $|\supp(\bm{y})| < |\supp(\bm{x})|$. Consequently, $p_F(\bm{y}) = p_F(\bm{t})$ for some $t < k$, contradicting $i_{k+1}(F) = p_F(\bm{k}) > p_F(\bm{t})$. Therefore, we must have $\bm{x} = \bm{k}$, and again $\OPT_{k+1}(F) = \{\bm{k}\}$.
    This completes the proof of Theorem~\ref{THM:almost-balanced-asymptotic} for $\ell \le 2r-1$.
\end{proof}

\subsection{Proof of Theorem~\ref{THM:almost-balanced-asymptotic} for $\ell \ge 2r$}\label{SUBSEC:proof-asymptotic-large}
In this subsection, we present the proof of Theorem~\ref{THM:almost-balanced-asymptotic} for $\ell \ge 2r$.
We will use the following inequality, which constitutes the most crucial ingredient of our proof and distinguishes our approach from those in~\cite{Brown94,Bollobas95,LiuMubayi23,Yuster26}. 
\begin{proposition}\label{PROP:a-b-ineq}
    Let $x$ and $y$ be two positive real numbers. 
    For positive integers $d, d_1, d_2$ define
    \begin{alignat*}{2}
        \mu_{d} & \coloneqq (x + y)^{d} - x^d - y^d, \qquad
        & \omega_{d} & \coloneqq x^{d} + y^{d} - 2\left(\tfrac{x+y}{2}\right)^{d}, \\
        \psi_{d_1, d_2} & \coloneqq x^{d_1} y^{d_2} + x^{d_2} y^{d_1}, \qquad
        & \phi_{d_1,d_2} & \coloneqq 2\left(\tfrac{x+y}{2}\right)^{d_1+d_2} - x^{d_1} y^{d_2} - x^{d_2} y^{d_1}. 
    \end{alignat*}
    Suppose that $x \neq y$, and let $a,b,s,t$ be positive integers satisfying $b \ge t \ge s \ge a >\binom{b-a}{2}$. 
    Then 
    \begin{equation}\label{eq:ratio-inequality}
        \frac{\omega_{t}}{\mu_{t}}
        \le \frac{\omega_{a}}{\mu_{a}}
        < \frac{\phi_{s,t}}{\psi_{s,t}}. 
    \end{equation}
    Equivalently, 
    \begin{align}\label{eq:ratio-inequality-b}
        \mu_{t} \omega_{a} - \mu_{a} \omega_{t} \geq 0, 
        \quad\text{and}\qquad  
        \mu_{a} \phi_{s,t} - \omega_{a} \psi_{s, t} > 0.
    \end{align}
\end{proposition}

\begin{proof}
    First we prove that $\frac{\omega_{t}}{\mu_{t}} \le \frac{\omega_{a}}{\mu_{a}}$, which follows from the following claim. 

    \begin{claim}\label{CLAIM:key-inequality-I}
        We have $\frac{\omega_{k+1}}{\mu_{k+1}} \le \frac{\omega_{k}}{\mu_{k}}$ for every integer $k \ge a$. 
    \end{claim}
    \begin{proof}
        By definition, this is equivalent to showing 
        \[
            \left( x^{k+1} + y^{k+1} - 2\left(\tfrac{x + y}{2}\right)^{k+1} \right) \left( (x + y)^{k} - x^{k} - y^{k} \right) 
            \leq \left( x^{k} + y^{k} - 2\left(\tfrac{x + y}{2}\right)^{k} \right) \left( (x + y)^{k+1} - x^{k+1} - y^{k+1} \right).
        \]
        Simplifying this reduces to showing that: 
        \begin{equation}\label{eq:rearranged-monotonicity}
            (x + y)^{k+1} \leq x^{k+1} + y^{k+1} + (2^k - 1)(x^k y + x y^k). 
        \end{equation}
        Since for every $i \in [k]$ it holds that  
        \begin{align*}
            (x^k y + x y^k) - (x^{i} y^{k+1-i} + x^{k+1-i} y^{i}) 
            = x y (x^{i-1} - y^{i-1})(x^{k-i} - y^{k-i}) 
            \ge 0, 
        \end{align*}
        it follows that 
        \begin{align*}
            \sum_{i=1}^{k} \tbinom{k+1}{i}(x^k y + x y^k) 
            & \ge \sum_{i=1}^{k} \tbinom{k+1}{i} x^{i} y^{k+1-i} + \sum_{i=1}^{k} \tbinom{k+1}{i} x^{k+1-i} y^{i}, 
        \end{align*}
        which implies that 
        \begin{align*}
            \left(2^{k+1}-2\right)(x^k y + x y^k) 
            \ge 2\left( (x+y)^{k+1} - \left(x^{k+1} + y^{k+1}\right) \right)
        \end{align*}
        After dividing both sides by $2$ and rearranging, we obtain~\eqref{eq:rearranged-monotonicity}.  
    \end{proof}    

    Next, we prove that $\frac{\omega_{a}}{\mu_{a}} < \frac{\phi_{s,t}}{\psi_{s,t}}$ for $b\geq t\geq s\geq a\geq 2$.
    By definition, this inequality is equivalent to
    \begin{align*}
        \big( (x + y)^{a} - x^{a} - y^{a} \big) \left( 2\left(\tfrac{x + y}{2}\right)^{s+t} - x^{s} y^{t} - x^{t} y^{s} \right) 
        > \left( x^{a} + y^{a} - 2\left( \tfrac{x + y}{2} \right)^{a} \right) \big( x^s y^t + x^t y^s \big).
    \end{align*}
    Simplifying this reduces to showing that: 
    \begin{align}\label{eq:simplification-RHS}
        \left( \tfrac{x+y}{2} \right)^{s+t-a} \big( (x + y)^{a} - x^{a} - y^{a} \big) 
        > \left( 2^{a-1}-1 \right) \left( x^s y^t + x^t y^s \right).
    \end{align}

    We first prove the following auxiliary inequalities:
    \begin{claim}
        The following inequalities hold:
        \begin{align}
            2^{a-2} \big( (x + y)^{a} - x^{a} - y^{a} \big) 
            & \ge (2^a-2) x y (x+y)^{a-2}; \label{eq:reduction-to-Sidorenko} \\[.4em]
            2\left( \tfrac{x+y}{2} \right)^{s+t-2} 
            & > x^{s-1} y^{t-1} + x^{t-1} y^{s-1}.  \label{eq:Sidorenko}
        \end{align}
    \end{claim}
    \begin{proof}
        First, we prove~\eqref{eq:reduction-to-Sidorenko}. 
        It is straightforward to verify that~\eqref{eq:reduction-to-Sidorenko} holds with equality when $a \in \{2,3\}$, so we may assume that $a \ge 4$. 
        For $i \in [a-1]$, let 
        \begin{align*}
            M_i 
            \coloneqq 2^{a-2} \tbinom{a}{i} - (2^a-2)\tbinom{a-2}{i-1},  
        \end{align*}
        noting that $M_{i} = M_{a-i}$.
        Let 
        \begin{align*}
            f(i)
            \coloneqq \tfrac{2^{a-2} \tbinom{a}{i}}{(2^a-2)\tbinom{a-2}{i-1}}
            = \tfrac{2^{a-2} a(a-1)}{(2^a-2)i(a-i)}.
        \end{align*}
        Observe that $f(i)$ is decreasing in $i$ for $i \in (0,a/2)$ and increasing in $i$ for $i \in (a/2, a)$. 
        Also 
        \begin{align*}
            f(1) = f(a-1) = \tfrac{2^{a-2} a}{2^a-2} > 1
            \quad\text{and}\quad 
            f(a/2) = \tfrac{2^{a-2} (a-1)}{(2^a-2)a} < 1. 
        \end{align*}
        So there exists $i_0 \in [2,a/2]$ such that 
        \begin{align*}
            \begin{cases}
                M_i > 0, &\quad\text{if}\quad i < i_0 \mbox{ or } i > a-i_0, \\
                M_i \le 0, &\quad\text{if}\quad i \in [i_0, a - i_0]. 
            \end{cases}
        \end{align*}
        For $i,j \in [1, a/2]$ with $i < j$, we have 
        \begin{align*}
            \left(x^{i} y^{a-i} + x^{a-i} y^{i}\right) - \left(x^{j} y^{a-j} + x^{a-j} y^j\right)
            = x^{i}y^{i} \left(x^{j-i} - y^{j-i} \right) \left(x^{a-i-j} - y^{a-i-j}\right)
            \ge 0. 
        \end{align*}

        Define $\gamma_{i} \coloneqq x^{i}y^{a-i}$ and $\beta_{i} \coloneqq (\gamma_{i} + \gamma_{a-i})/2$ for $i \in [1, a/2]$. 
        The inequality above shows that for $i < j \leq a/2$, we have $\gamma_i+\gamma_{a-i} \geq \gamma_j+ \gamma_{a-j}$ and consequently $\beta_i \geq \beta_j$.
        Also note that 
        \begin{align*}
            \sum_{i=1}^{a-1} M_{i}
            = 2^{a-2} \sum_{i=1}^{a-1} \tbinom{a}{i} - \left(2^{a}-2\right) \sum_{i=1}^{a-1} \tbinom{a-2}{i-1}
            = 2^{a-2} \left(2^a - 2\right) - \left(2^{a}-2\right) 2^{a-2}
            = 0, 
        \end{align*}
        Then, using the Binomial Theorem and the symmetry $M_i=M_{a-i}$ and $\beta_i=\beta_{a-i}$, we obtain that
        \begin{align*}
            & 2^{a-2} \big( (x + y)^{a} - x^{a} - y^{a} \big) 
            - (2^a-2) x y (x+y)^{a-2} \\
            = &\sum_{i=1}^{a-1} M_{i} \gamma_{i}
            = \frac{1}{2} \sum_{i=1}^{a-1} \left( M_{i} \gamma_{i} + M_{a-i} \gamma_{a-i} \right)
            = \sum_{i=1}^{a-1} M_{i} \beta_{i}
            = \sum_{i=1}^{i_0-1} M_{i} \beta_{i} + \sum_{i=i_0}^{a-i_0} M_{i} \beta_{i} +  \sum_{i=a-i_0+1}^{a-1} M_{i} \beta_{i} \\
            \geq &\left ( \sum_{i=1}^{i_0-1} M_{i} \right ) \min_{1\leq i \leq i_0-1} \beta_i +  \left ( \sum_{i=i_0}^{a-i_0} M_{i} \right ) \max_{i_0\leq i \leq a-i_0} \beta_i + \left ( \sum_{i=a-i_0+1}^{a-1} M_{i} \right) \min_{a-i_0+1\leq i \leq a-1} \beta_i \\
            =  &\left ( \sum_{i=1}^{i_0-1} M_{i} \right ) \beta_{i_0-1} +  \left ( \sum_{i=i_0}^{a-i_0} M_{i} \right ) \beta_{i_0} + \left ( \sum_{i=a-i_0+1}^{a-1} M_{i} \right) \beta_{a-i_0+1}
            = 2 \left( \sum_{i=1}^{i_0-1} M_{i} \right ) \left(\beta_{i_0-1} - \beta_{i_0} \right) 
            \geq 0, 
        \end{align*}
        where the last equation uses the symmetry and the fact that $\sum_{i=1}^{a-1} M_i=0$.
        This proves~\eqref{eq:reduction-to-Sidorenko}. 

        \bigskip 

        It remains to prove~\eqref{eq:Sidorenko}. 
        The argument is adapted from the proof of~\cite[Theorem 3]{Brown94}, with some modifications.
        Define, for every $z \in [0,1]$, 
        \begin{align*}
            g(z) \coloneqq z^{t-1}(1-z)^{s-1} + z^{s-1}(1-z)^{t-1}
        \end{align*}
        We first show that $g$ attains its maximum uniquely at $z = 1/2$.

        Letting $x \coloneqq (1-z)/z$.
        Straightforward calculations show that 
        \begin{align*}
            g'(z) = z^{t-1}(1-z)^{s-2} \Bigl( (s-1)x^{t-s+1} - (t-1)x^{t-s} + (t-1)x - s + 1 \Bigr),
        \end{align*}
        Define 
        \begin{align*}
            h(x) \coloneqq (s-1)x^{t-s+1} - (t-1)x^{t-s} + (t-1)x - s + 1
        \end{align*}
        Let $y \coloneqq x - 1$. Then for $x\ge 1$, we have 
        \begin{align*}
            h(x) &= (s-1)(1+y)^{t-s+1} - (t-1)(1+y)^{t-s} + (t-1)(1+y) - s + 1 \\
            &= \Bigl( (s-1)(t-s+1) - (t-1)(t-s) + (t-1) \Bigr) y 
            + \sum_{i=2}^{t-s+1} \bigl( (s-1)\tbinom{t-s+1}{i} - (t-1)\tbinom{t-s}{i} \bigr) y^i \\
            &= 2\Bigl( s - 1 - \tbinom{t-s}{2} \Bigr) y 
            + \sum_{i=2}^{t-s+1} \tbinom{t-s}{i-1} \frac{1}{i} 
            \Bigl( (s-1)(t-s+1) - (t-1)(t-s-i+1) \Bigr) y^i \\
            &\geq 2\Bigl( s - 1 - \tbinom{t-s}{2} \Bigr) y 
            + \sum_{i=2}^{t-s+1} \tbinom{t-s}{i-1} \frac{1}{i} 
            \Bigl( (s-1)(t-s+1) - (t-1)(t-s-1) \Bigr) y^i \\
            &= 2\Bigl( s - 1 - \tbinom{t-s}{2} \Bigr) y 
            + \sum_{i=2}^{t-s+1} \tbinom{t-s}{i-1} \frac{2}{i} \Bigl( s - 1 - \tbinom{t-s}{2} \Bigr) y^i 
            \ge 0, 
        \end{align*}
        where in the last inequality we used the assumption that $\binom{b-a}{2} \le a-1$ (and thus, $s - 1 \geq a - 1 \geq \binom{b-a}{2} \geq \binom{t-s}{2}$).

        It follows that $g'(z) \ge 0$ for $z\in(0,1/2)$, and hence, $g$ is nondecreasing on $[0, 1/2]$.
        Since $g$ is symmetric around $z=1/2$ and is a polynomial which is not linear (since $s, t \ge 2$), it attains its maximum on the interval $[0,1]$ uniquely at $z=1/2$. 
        Therefore,~\eqref{eq:Sidorenko} holds.
    \end{proof}

    Combining~\eqref{eq:reduction-to-Sidorenko} and~\eqref{eq:Sidorenko}, we obtain
    \begin{align*}
        \left( \tfrac{x+y}{2} \right)^{s+t-a} \big( (x + y)^{a} - x^{a} - y^{a} \big) 
        & \ge \left( \tfrac{x+y}{2} \right)^{s+t-a} \left(2^a-2\right) xy \left( \tfrac{x+y}{2} \right)^{a-2} \\[.4em]
        & > \tfrac{2^a-2}{2} xy \left(x^{s-1} y^{t-1} + x^{t-1} y^{s-1}\right) 
        = \left( 2^{a-1}-1 \right) \left( x^s y^t + x^t y^s \right), 
    \end{align*}
    which proves~\eqref{eq:simplification-RHS}. 
    This completes the proof of Proposition~\ref{PROP:a-b-ineq}.
\end{proof}

We are now ready to prove Theorem~\ref{THM:almost-balanced-asymptotic} for $\ell \ge 2r$. 
\begin{proof}[\bf Proof of Theorem~\ref{THM:almost-balanced-asymptotic} for $\ell \ge 2r$]
    Let $F = K_{a_1, \ldots, a_{r}}$ be an almost balanced complete $r$-partite graph on $\ell \ge 2r$ vertices, that is, $\ell = a_1 + \cdots + a_r$.
    Let $m = m_{r,\ell}$ be the integer give by Lemma~\ref{Lemma:Unique-Maximizer}. 
    Assume that $a_1 \ge \cdots \ge a_r$. 
    By Fact~\ref{FACT:almost-balanced-sizes}~\ref{FACT:almost-balanced-sizes-2}, we have $a_r \ge 2$. 
    Fix an integer $k \in [r, \infty]$.

    \begin{claim}\label{CLAIM:large-opt-x0}
        For every $\bm{x} \in \OPT_{k}(F)$, we have $x_0 = 0$. 
    \end{claim}
    \begin{proof}
        It follows from the definition of $\mathbb{S}^{k-1}$ that $x_0 = 0$ if $k \neq \infty$. Thus we may assume that $k = \infty$. 
        Suppose to the contrary that there exists $\bm{x} = (x_1, x_2, \ldots) \in \OPT(F)$ with $x_0 > 0$. 
        Since in every realization $G_{n,\bm{{x}}}$ (see Definition~\ref{DEF:realization}), no induced copy of $F$ can contain vertices from $V_0$ (because $a_1 \ge \cdots \ge a_r \ge 2$), we have  
        \begin{align*}
            p_{F}(\bm{x})
            = \kappa_{F} \cdot \sum_{(i_1, \ldots, i_{r}) \in (\mathbb{N}_{+})_{r}} x_{i_1}^{a_1} \cdots x_{i_{r}}^{a_r}. 
        \end{align*}
        Let $\tilde{\bm{x}}$ be the sequence obtained from $\bm{x}$ by replacing $x_1$ with $x_0+x_1$. 
        Note that $\tilde{\bm{x}} \in \overline{\mathcal{P}}$ and $p_{F}(\tilde{\bm{x}}) - p_{F}(\bm{x}) > 0$, a contradiction to the optimality of $\bm{x}$. 
    \end{proof}    
    Fix an arbitrary optimal sequence $\bm{x} \in \OPT_{k}(F)$.
    By Claim~\ref{CLAIM:large-opt-x0}, we have $x_0 = 0$. 
    We aim to show that all nonzero entries of $\bm{x}$ are equal. 
    Suppose to the contrary that there exist $i, j \in \supp(\bm{x})$ with $x_i \neq x_j$. 

    Let $\bm{y}$ and $\bm{z}$ be the sequence in $\overline{\mathcal{P}}$ obtained from $\bm{x}$ by replacing $(x_i,x_j)$ with $(x_i+x_j,0)$ and $\left(\frac{x_i+x_j}{2}, 
    \frac{x_i+x_j}{2}\right)$, respectively, and then reordering the entries accordingly.
    Note that $y_0 = z_0 = x_0 = 0$ and $\{\bm{y}, \bm{z}\} \subseteq \mathbb{S}^{k-1}$.
    In addition, define $\tilde{\bm{x}}$ by replacing both $x_i$ and $x_j$ with $0$ and then reordering the entries.

    Let $\bm{a} \coloneqq (a_1, \ldots, a_r)$.
    Recall the definition of $S_{\bm{a}}(\bm{x})$ from \eqref{equ:def-S-polynomial}.
    We shall prove the following key inequality: 
    \begin{claim}\label{CLAIM:large-shifting-increase}
        We have 
        \begin{align}\label{equ:large-opt-key-inequality}
            S_{\bm{a}}(\bm{x}) 
            < \max \big\{ S_{\bm{a}}(\bm{y}),~S_{\bm{a}}(\bm{z})\}. 
        \end{align}
        Consequently, $p_{F}(\bm{x}) < \max \big\{ p_{F}(\bm{y}),~p_{F}(\bm{z})\}$.
    \end{claim}
    \begin{proof}
        For $p, q \in [r]$, let $\bm{a}^{p}$ be the $(r-1)$-tuple obtained from $\bm{a}$ by removing the element $a_{p}$; let $\bm{a}^{p,q}$ be the $(r-2)$-tuple obtained from $\bm{a}$ by removing the elements $a_{p}$ and $a_{q}$; 
        and let 
        \begin{align*}
            A_{p}
            \coloneqq S_{\bm{a}^{p}}(\tilde{\bm{x}})
            \quad\text{and}\quad 
            B_{p,q} 
            \coloneqq S_{\bm{a}^{p,q}}(\tilde{\bm{x}}).
        \end{align*}
        It is clear that $|\supp(\bm{x})| \ge r$. 
        Thus, $|\supp(\tilde{\bm{x}})| \ge r-2$, and hence, $B_{p,q} > 0$ for all $\{p, q\} \subseteq [r]$. 
        Define 
        \begin{alignat*}{2}
            \mu_{p} & \coloneqq (x_i + x_j)^{a_{p}} - x_i^{a_{p}} - x_j^{a_{p}}, \qquad
            & \omega_{p} & \coloneqq x_i^{a_{p}} + x_j^{a_{p}} - 2\left(\tfrac{x_i+x_j}{2}\right)^{a_{p}}, \\
            \psi_{p, q} & \coloneqq x_i^{a_p} x_j^{a_q} + x_i^{a_q} x_j^{a_p}, \qquad
            & \phi_{p, q} & \coloneqq 2\left(\tfrac{x_i+x_j}{2}\right)^{a_p + a_q} - x_i^{a_p} x_j^{a_q} - x_i^{a_q} x_j^{a_p}. 
        \end{alignat*}
        Suppose to the contrary that this claim fails. 
        Then we have 
        \begin{align}
            0 
            \leq S_{\bm{a}}(\bm{x}) - S_{\bm{a}}(\bm{y})
            & = -\sum_{p\in [r]} \mu_{p} A_p + \sum_{\{p,q\} \in \binom{[r]}{2}} \psi_{p,q} B_{p,q},  \label{eq:ineq1} \\[.3em]
            0 
            \leq S_{\bm{a}}(\bm{x}) - S_{\bm{a}}(\bm{z})
            & = \sum_{p\in [r]} \omega_{p} A_{p} - \sum_{\{p,q\} \in \binom{[r]}{2}} \phi_{p,q} B_{p,q}. \label{eq:ineq2}
        \end{align}
        Considering the linear combination $-\omega_{r} \times~\eqref{eq:ineq1} - \mu_{r} \times~\eqref{eq:ineq2}$, we obtain 
        \begin{align}\label{eq:point-of-contradiction}
            \sum_{p\in [r]} (\mu_{p} \omega_{r} - \mu_{r} \omega_{p}) A_p + \sum_{\{p,q\} \in \binom{[r]}{2}} (\mu_{r} \phi_{p,q} - \omega_{r} \psi_{p, q}) B_{p,q} \leq 0.
        \end{align}

        However, it follows from~\eqref{eq:ratio-inequality-b} and $B_{p,q} > 0$ that 
        \begin{align*}
            \sum_{p\in [r]} (\mu_{p} \omega_{r} - \mu_{r} \omega_{p}) A_p + \sum_{\{p,q\} \in \binom{[r]}{2}} (\mu_{r} \phi_{p,q} - \omega_{r} \psi_{p, q}) B_{p,q}
            > 0, 
        \end{align*}
        a contradiction to~\eqref{eq:point-of-contradiction}. 
    \end{proof}
    It follows from Claim~\ref{CLAIM:large-shifting-increase} and the optimality of $\bm{x}$ that $\bm{x}$ must be balanced. 
    Suppose that $|\supp(\bm{x})| = \hat{k}$ for some integer $\hat{k} \le k$. Then $\bm{x} = \bm{\hat{k}} = (1/\hat{k}, \ldots, 1/\hat{k}, 0, \ldots)$, and hence, $p_{F}(\bm{x}) = \kappa_{F} \cdot {(\hat{k})_{r}}/{\hat{k}^{r}}$. 
    It follows from Lemma~\ref{Lemma:Unique-Maximizer} and the maximality of $p_{F}(\bm{x})$ that $\hat{k} = m$ if $k \ge m$ and $\hat{k} = k$ if $k \le m-1$. 
    This completes the proof of Theorem~\ref{THM:almost-balanced-asymptotic} for $\ell \ge 2r$.
\end{proof}
\section{Perfect stability}\label{Sec:Stablity}
\subsection{Preparations}
In this subsection, we briefly review the sufficient conditions for perfect stability in the framework developed by~\cite{LiuPikhurko23}. Their framework applies to the broader class of “symmetrizable” functions, but here we focus specifically on the inducibility problem for complete multipartite graphs $F$. Very roughly, \cite[Theorem 1.1]{LiuPikhurko23} asserts that if $\OPT(F)$ is finite and each maximizer $\bm{x} \in \OPT(F)$ satisfies certain \emph{strictness} conditions, then the inducibility problem for $F$ is perfectly stable. 

For convenience, we will use the following simplified variant of~\cite[Theorem 1.1]{LiuPikhurko23} (see also~\cite[Theorem 8.2]{Basit25}).

For a graph $G$ and a pair $\{x,y\} \subseteq V(G)$ of vertices, let $G \oplus xy$ denote the graph with vertex set $V(G)$ and edge set $E(G) \bigtriangleup \{xy\}$.
That is, $G \oplus \{xy\}$ is obtained by adding the edge $\{x,y\}$ if it is not present in $G$, and by removing it otherwise.
Suppose that $G$ is a complete $t$-partite graph with parts $V_1,\ldots,V_t$.
For every $A \subseteq [t]$, let $G_A$ denote the graph obtained from $G$ by adding a new vertex that is adjacent precisely to all vertices in $\bigcup_{i \in A} V_i$.

\begin{theorem}\label{THM:Stability-Verification}
    Let $F$ be a complete multipartite graph with $\ell$ vertices. 
    Suppose that $\OPT(F)$ contains a unique sequence $\bm{x}$ with $x_0 = 0$ (i.e. $\sum_{i\in \mathbb{N}_{+}}x_i = 1$) and $t \coloneqq |\supp(\bm{x})| < \infty$.
    Suppose that there exist constants $\varepsilon > 0$ and $N_0$ such that for every $n \ge N_0$ the following statements hold for the $n$-vertex realization $G \coloneqq G_{n,\bm{x}}$ with parts $V_1, \ldots, V_t \colon$ 
    \begin{enumerate}[label=(S\arabic*), ref=S\arabic*]
        \item\label{cond:S1} For every pair $\{x,y\} \subseteq V(G)$, we have 
            \begin{align*}
                I(F, G) - I(F, G \oplus xy) 
                \geq \varepsilon n^{\ell-2}.
            \end{align*}
        \item\label{cond:S2} For every $A \subseteq [t]$ with $|A| \neq t-1$, we have 
            \[
               \min\big\{ I(F, G_{A^{\ast}}) \colon A^{\ast} \subseteq [t] \text{ and } |A^{\ast}| = t-1 \big\} - I(F, G_A) 
                \geq \varepsilon n^{\ell-1}.
            \]
    \end{enumerate}

