        \frac{m-r}{m} < \left( 1- \frac{1}{m} \right)^{\ell}.
    \end{align}
    Combining it with the inequality 
    \begin{align*}
        \left( 1- \frac{1}{m} \right)^{\ell}\leq1-\frac{\ell}{m}+\binom{\ell}{2}\left(\frac{1}{m}\right)^2, 
    \end{align*}
    we obtain $m <  \frac{\ell(\ell-1)}{2(\ell-r)}$. 

    It remains to prove that $m < r/\alpha$. 
    Define $\theta \coloneqq r/m$. 
    Then it follows from~\eqref{eq:m-upper-bound} and the inequality $\ln(1+x) \le x$ for $x > -1$ that 
    \begin{align*}
        1-\theta 
        = \frac{m-r}{m}
        < \left( 1- \frac{1}{m} \right)^{\ell} 
        = \exp\left(\ell \ln\left(1-\frac{1}{m}\right) \right) 
        \le \exp\left(-\frac{\ell}{m}\right) 
        = \mathrm{e}^{-t\theta}.
    \end{align*}
    In other words, we have $h_t(\theta)< 0$.
    Since $h_t$ is unimodal on $(0,\infty)$ and $h_{t}(0) = 0$, we have $\theta > \alpha$, which implies that $m < r/\alpha$.
    This proves~\ref{Lemma:m-upper-bound}, and thus completing the proof of Lemma~\ref{Lemma:m-bounds}.
\end{proof}
\subsection{Proof of Theorem~\ref{THM:almost-balanced-perfect-stability} for $\ell < 2r$}\label{SUBSEC:proof-perfect-stability-small}
In this subsection, we present the proof of Theorem~\ref{THM:almost-balanced-perfect-stability} for $\ell < 2r$. 

\begin{lemma}\label{LEMMA:stable-small-inequality}
    Let $\ell, r$ be integers such that $r\ge 2$ and $r+1 \le \ell \le 2r-1$. 
    Let $m = m_{r,\ell}$ be the integer given by Lemma~\ref{Lemma:Unique-Maximizer}. 
    Then the discrete function $h \colon [0, m] \to \mathbb{Z}$ defined by 
    \begin{align*}        h(q)
        \coloneqq (q)_{r-1}\cdot \bigl(2r-\ell+2(m-q)(\ell-r)\bigr), 
        \quad\text{for every}\quad q \in [0, m], 
    \end{align*}
    satisfies $h(q) < h(m-1)$ for all integers $q \in [0, m] \setminus \{m-1\}$. 
\end{lemma}
\begin{proof}
    Note that $h(m-1) = \ell (m-1)_{r-1} > 0$. So it suffices to prove that for every $q \in [r-1, m] \setminus\{m-1\}$, 
    \begin{align}\label{equ:small-stable-inequality}
        h(q)
        = (q)_{r-1}\cdot \bigl(2r - \ell + 2(m-q)(\ell - r)\bigr) 
        < \ell (m-1)_{r-1}.
    \end{align}

